class Foo {
    private val asyncPool = Executors.newFixedThreadPool(8)

    fun bad(accounts: List<Any>) {
        val futures = accounts.map {
            CompletableFuture.supplyAsync { isAccountBlocked(it) } // bad, uses common pool
        }
    }

    fun good(accounts: List<Any>) {
        val futures = accounts.map {
            CompletableFuture.supplyAsync({ isAccountBlocked(it) }, asyncPool) // good
        }
    }
}

