import java.util.concurrent.ConcurrentHashMap
class Cache {
    private val store = ConcurrentHashMap<String, String>()
    fun bad(key: String, value: String) {
        if (!store.containsKey(key)) store.put(key, value) // bad: race condition
    }
    fun good(key: String, value: String) = store.putIfAbsent(key, value) // ok: atomic
}

