    fun mutateMapBad(key: String, value: String) {
        map.put(key, value) // bad - unguarded mutator on inherited field
    }
}

@org.springframework.stereotype.Component
class Good : SomeParent() {
    @Synchronized
    fun mutateMapGood(key: String, value: String) {
        map.put(key, value) // good - synchronized
    }
