rule.example:
class BadHttpClientV5 {
    public HttpClient createClient() {
        RequestConfig requestConfig = RequestConfig.custom()
                .setResponseTimeout(Timeout.ofMilliseconds(1200))
                .build();

        return HttpClients.custom()
                .build();
    }
}

class GoodHttpClientV5 {
    public CloseableHttpClient createHttpClient() {
        ConnectionConfig connectionConfig = ConnectionConfig.custom()
                .setConnectTimeout(Timeout.ofMilliseconds(300))
                .build();

        PoolingHttpClientConnectionManager connectionManager =
                PoolingHttpClientConnectionManagerBuilder.create()
                        .setDefaultConnectionConfig(connectionConfig)
                        .build();

        RequestConfig requestConfig = RequestConfig.custom()
                .setConnectionRequestTimeout(Timeout.ofMilliseconds(100))
                .setResponseTimeout(Timeout.ofMilliseconds(1200))
                .build();

        return HttpClients.custom() // good, all expected overrides for timeouts
                .setDefaultRequestConfig(requestConfig)
                .setConnectionManager(connectionManager)
                .build();
    }
}


import javax.xml.bind.JAXBContext

class Bad {
    fun marshal(obj: Any): String {
        val ctx = JAXBContext.newInstance(obj::class.java) // bad: recreated per call
        return ctx.createMarshaller().run { java.io.StringWriter().also { marshal(obj, it) }.toString() }
    }
}
class Good {
    companion object {
        private val CTX = JAXBContext.newInstance(Good::class.java) // ok: created once
    }
}

