rule.example:

fun connectionProviderBad(): ConnectionProvider {
    return ConnectionProvider.builder("myProvider").build() // bad
}
fun connectionProviderGood(): ConnectionProvider {
    return ConnectionProvider.builder("myProvider")
        .maxConnections(props.maxConnections)
        .pendingAcquireTimeout(props.pendingAcquireTimeoutMs)
        .build()
}

